  applicationStatusHistory?: Prisma.ApplicationStatusHistoryOmit
  applicationNote?: Prisma.ApplicationNoteOmit
  submission?: Prisma.SubmissionOmit
  interview?: Prisma.InterviewOmit
  interviewFeedback?: Prisma.InterviewFeedbackOmit
  offer?: Prisma.OfferOmit
  joining?: Prisma.JoiningOmit
  employee?: Prisma.EmployeeOmit
  document?: Prisma.DocumentOmit
  documentAccessLog?: Prisma.DocumentAccessLogOmit
